String topologicalSort(Iterable<int> indegree) {
  var graph = new LinkedListQueue<int>();
  for (var i = 0; i < indegree.length; i++) {
    if (indegree[i] == 0) graph.add(i);
  }
  List<int> order = new ListQueue<int>();
  while (graph.isNotEmpty) {
    int vertex = graph.removeFirst();
    order.add(vertex);
    for (int i = 0; i < indegree.length; i++) {
      if (i != vertex && indegree[i] == indegree[vertex] - 1) {
        indegree[i] = indegree[i] - 1;
        if (indegree[i] == 0) graph.add(i);
      }
    }
  }
  if (order.length == indegree.length) {
    return "Topological Sort: " + order.join(' ');
  } else {
    return "Graph contains a cycle, topological sort not possible.";
  }
}

#include <stdio.h>
#include <stdlib.h>

void print_graph(const char* name, const int* graph_size, const int** graph) {
    printf("%s\n", name);
    for (int i = 0; i < *graph_size; ++i) {
        for (int j = 0; j < *graph_size; ++j) {
            if (graph[i][j] == 1) {
                printf("%d -> %d\n", i, j);
            }
        }
    }
}

