fn fn0(String word) {
  const String wordBank =
      "and cat dog pen cats code leet pine sand apple applepen leetcode";

  // string tokenizing
  var words = wordBank.split(' ');

  var dictionary = new Map<String, List<String>>.from(words);

  // word break (can segment?)
  if (dictionary.containsKey(word)) {
    print('String: "$word"');
    print('Can segment: true');
    print(', Dictionary: $dictionary');
    print('Minimum words needed: ${dictionary[word].length}');
    print('=== Word Break (Can Segment?) ===');
    print(word);
    print('=== Word Break II (All Segmentations) ===');
    print(word);
    for (var split in splitWord(word)) {
      print(split);
    }
    return;
  }

  print('String: "$word"');
  print('Cannot segment');
  print(', Dictionary: $dictionary');
  print('Minimum words needed: ${words.length}');
  print('=== Word Break (Can Segment?) ===');
  print(word);
  print('=== Word Break II (All Segmentations) ===');
  print(word);
  print('Cannot segment');
}

// split word, possibly in a non-greedy way
List<String> splitWord(String word) {
  var segments = [];

  for (int i = 0; i < word.length; i++) {
    if (dictionary.containsKey(word.substring(0, i + 1))) {
      segments.add(word.substring(0, i + 1));
      word = word.substring(i + 1);
      continue;
    }
  }

  if (word.isNotEmpty) {
    segments.add(word);
  }

  return segments;
}

