BigInt modularInverse(BigInt a, BigInt m) {
  final gcd = _gcd(a, m);
  if (gcd != 1) {
    return BigInt.zero;
  }
  final b = _modInverse(a, m);
  if (b < 0) {
    return m + b;
  }
  return b;
}

BigInt _modInverse(BigInt a, BigInt m) {
  final n = m.toUnsigned();
  BigInt x = 0, y = 1;
  if (m == 1) {
    return 0;
  }
  while (a > 1) {
    final q = a ~/ m;
    final t = m;
    m = a % m;
    a = t;
    t = x;
    x = y - q * x;
    y = t;
  }
  if (y < 0) {
    y += n;
  }
  return y;
}

BigInt _gcd(BigInt a, BigInt b) {
  final n = a.toUnsigned();
  BigInt x = 0, y = 1;
  BigInt aTemp = a.toUnsigned();
  BigInt bTemp = b.toUnsigned();
  while (bTemp != 0) {
    final q = aTemp ~/ bTemp;
    final t = bTemp;
    bTemp = aTemp % bTemp;
    aTemp = t;
    t = x;
    x = y - q * x;
    y = t;
  }
  if (y < 0) {
    y += n;
  }
  return y;
}

