/// An undirected graph implemented as a [Map] of [Node].
///
/// This implementation assumes that each node has only one parent
/// (making this a directed graph), and that the nodes are pairwise connected
/// only by edges.
///
/// See also: [Graph]
class DirectedGraph implements Graph {
  const DirectedGraph();

  /// Creates a new [DirectedGraph].
  factory DirectedGraph.fromFiles(String file1, String file2) {
    var g = DirectedGraph();

    var file1Text = File(file1).readAsStringSync();
    var file2Text = File(file2).readAsStringSync();

    var file1Edges = file1Text
        .split('\n')
        .map((e) => e.trim().split(' '))
        .map(nodes.Node.parse)
        .toList();
    var file2Edges = file2Text
        .split('\n')
        .map((e) => e.trim().split(' '))
        .map(nodes.Node.parse)
        .toList();

    file1Edges.forEach((e) {
      var p = g.add(e[0]);
      if (e.length > 1) {
        var c = g.add(e[1]);
        p.add(c);
      }
    });
    file2Edges.forEach((e) {
      var p = g.add(e[1]);
      if (e.length > 1) {
        var c = g.add(e[0]);
        p.add(c);
      }
    });

    return g;
  }

  /// Creates a new [DirectedGraph] from the given [Iterable] of [Node]s.
  factory DirectedGraph.fromIterable(Iterable<Node> nodes) {
    var g = DirectedGraph();
    nodes.forEach(g.add);
    return g;
  }

  /// Creates a new [DirectedGraph] from the given [Map].
  factory DirectedGraph.fromMap(Map<Node, Set<Node>> map) {
    return DirectedGraph(map: map);
  }

  /// The set of nodes in this graph.
