  /// Returns the node with the given [id].
  ///
  /// Throws a [StateError] if the node does not exist in this graph.
  Node getNode(int id) {
    var node = nodes.firstWhereOrNull((n) => n.id == id);
    if (node == null) {
      throw StateError('Node $id does not exist in this graph.');
    }
    return node;
