  /// was not added.
  Node add(Node node) {
    var id = node.id;
    var existed = nodes.firstWhereOrNull((n) => n.id == id);
    if (existed != null) {
      return existed;
    }

    var newId = nodes.length + 1;
    var newNode = Node(id: newId);
    nodes.add(newNode);
    edgeSet.add(Edge(newNode, null));

    return newNode;
  }

