  Node addEdge(Node from, Node to) {
    var edge = Edge(from, to);
    if (edgeSet.add(edge)) {
      if (parents[from] == null) {
        parents[from] = Set<Node>();
      }
      parents[from].add(to);

      neighbors[from] ??= Set<Node>();
      neighbors[from].add(to);

      if (parents[to] == null) {
        parents[to] = Set<Node>();
